import { useMemo } from "react";
import {
  selectReconstructionForSelectedElement,
  selectSkillMemory,
  useInspectorStore,
} from "../../store";
import type { selectSkillForSelectedElement } from "../../store/selectors";
import type { UnionEventType } from "../../types";
import type { SkillState } from "../../types/skill";
import { deriveSkillStateAt } from "./deriveSkillStateAt";
import { evaluateCondition } from "./conditionPhrase";

type ActiveSkill = NonNullable<ReturnType<typeof selectSkillForSelectedElement>>;
type ConditionMemory = Record<string, { value: unknown }> | null | undefined;

export interface ResolvedSkillState {
  /** True while a selection resolved to a skill via time-travel (historical mode). */
  readonly isHistorical: boolean;
  readonly evaluatedConditions: SkillState["evaluated_conditions"] | undefined;
  readonly toolGateStatuses: SkillState["tools"] | undefined;
  readonly blockStatuses: SkillState["blocks"] | undefined;
  readonly conditionMemory: ConditionMemory;
  readonly flowId: string | null;
  readonly stepId: string | null;
  /** Full conversation event list and cut-off for computing per-block step trails. */
  readonly events: UnionEventType[];
  readonly anchorIndex: number;
}

/**
 * Resolves the runtime state the skill pane renders — either reconstructed by
 * replaying the tracker up to the selected element (historical mode) or the
 * engine-reported live state.
 *
 * Historical mode replays the tracker events up to the anchor (the tracker
 * events ARE the replay data): block statuses, memory, and the flow/step
 * position at that point. Conditions are re-evaluated over the reconstructed
 * memory; tool gates carry no expression in the catalog, so they stay unknown
 * (neutral). Live mode keeps the engine-reported state.
 */
export function useResolvedSkillState(activeSkill: ActiveSkill | undefined): ResolvedSkillState {
  const liveSkillMemory = useInspectorStore(selectSkillMemory);
  const reconstruction = useInspectorStore(selectReconstructionForSelectedElement);
  const liveEvaluatedConditions = useInspectorStore((s) => s.skillState?.evaluated_conditions);
  const liveToolGateStatuses = useInspectorStore((s) => s.skillState?.tools);
  const liveBlockStatuses = useInspectorStore((s) => s.skillState?.blocks);
  const liveEvents = useInspectorStore((s) => s.conversationList.at(-1)?.events ?? []);

  const isHistorical = !!activeSkill && !!reconstruction;
  const reconstructed = useMemo(
    () =>
      isHistorical
        ? deriveSkillStateAt(
            reconstruction.events,
            reconstruction.anchorIndex,
            reconstruction.anchoredSkillId,
            activeSkill.skill,
          )
        : undefined,
    [isHistorical, reconstruction, activeSkill],
  );

  const evaluatedConditionsFromMemory = useMemo(() => {
    if (!reconstructed) return undefined;
    const results: Record<string, boolean> = {};
    for (const section of activeSkill?.skill.sections ?? []) {
      if (section.type !== "prose") continue;
      for (const segment of section.segments) {
        if (segment.condition === null) continue;
        const result = evaluateCondition(segment.condition, reconstructed.memory);
        if (result !== undefined) results[segment.condition] = result;
      }
    }
    return results;
  }, [reconstructed, activeSkill]);

  return {
    isHistorical,
    evaluatedConditions: isHistorical ? evaluatedConditionsFromMemory : liveEvaluatedConditions,
    // Tool gate expressions are not in the catalog, so historical gates are not
    // evaluable — undefined renders them neutral (unknown), never fabricated.
    toolGateStatuses: isHistorical ? undefined : liveToolGateStatuses,
    blockStatuses: isHistorical ? reconstructed?.blocks : liveBlockStatuses,
    conditionMemory: isHistorical ? reconstructed?.memory : liveSkillMemory,
    // Historical position comes from the replay; live mode from the active-skill ref.
    flowId: isHistorical ? (reconstructed?.position.flowId ?? null) : (activeSkill?.flowId ?? null),
    stepId: isHistorical ? (reconstructed?.position.stepId ?? null) : (activeSkill?.stepId ?? null),
    events: isHistorical ? (reconstruction?.events ?? []) : liveEvents,
    anchorIndex: isHistorical ? (reconstruction?.anchorIndex ?? -1) : liveEvents.length - 1,
  };
}
